canvas.width=W;canvas.height=H;
const materialRoot=document.getElementById('materials');
mats.forEach((m,n)=>{const b=document.createElement('button');b.className='material'+(n===0?' selected':'');b.dataset.id=m.id;b.innerHTML='<i class="swatch" style="background:'+m.swatch+'"></i><span class="mat-label">'+m.name+'</span>';b.addEventListener('click',()=>selectMaterial(m.id));materialRoot.appendChild(b)});
function selectMaterial(id){selected=id;erase=false;document.querySelectorAll('.material').forEach(b=>b.classList.toggle('selected',Number(b.dataset.id)===id))}
function pointerCell(ev){const r=canvas.getBoundingClientRect();return{x:Math.max(0,Math.min(W-1,Math.floor((ev.clientX-r.left)/r.width*W))),y:Math.max(0,Math.min(H-1,Math.floor((ev.clientY-r.top)/r.height*H)))}}
canvas.addEventListener('pointerdown',ev=>{ev.preventDefault();canvas.setPointerCapture(ev.pointerId);painting=true;erase=ev.button===2;if(!erase)erase=false;lastPoint=pointerCell(ev);paintAt(lastPoint.x,lastPoint.y);});
canvas.addEventListener('pointermove',ev=>{if(!painting)return;const p=pointerCell(ev);drawLine(lastPoint,p);lastPoint=p});
for(const event of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(event,()=>{painting=false;lastPoint=null});
canvas.addEventListener('contextmenu',ev=>ev.preventDefault());
document.getElementById('size').addEventListener('input',ev=>{brush=Number(ev.target.value);document.getElementById('sizeValue').textContent=brush+' px'});
document.getElementById('density').addEventListener('input',ev=>{density=Number(ev.target.value);document.getElementById('densityValue').textContent=density+'%'});
function togglePause(){running=!running;document.getElementById('pauseBtn').textContent=running?'Ⅱ':'▶';document.getElementById('pauseBtn').classList.toggle('active',!running);document.getElementById('runText').textContent=running?'Simulation running':'Simulation paused';document.getElementById('runDot').style.background=running?'var(--accent)':'#ffcc70'}
document.getElementById('pauseBtn').addEventListener('click',togglePause);
document.getElementById('stepBtn').addEventListener('click',()=>{if(!running){update();render()}});
document.getElementById('clearBtn').addEventListener('click',()=>{clearWorld();render()});
document.getElementById('fillBtn').addEventListener('click',()=>{for(let x=0;x<W;x++)for(let y=H-7;y<H;y++)setCell(x,y,STONE);setScene('A solid foundation')});
document.getElementById('rainBtn').addEventListener('click',()=>{for(let n=0;n<460;n++){const x=Math.floor(Math.random()*W),y=Math.floor(Math.random()*28);if(cells[index(x,y)]===EMPTY)setCell(x,y,selected===STONE?SAND:selected)}setScene('A little shower')});
document.getElementById('soundBtn').addEventListener('click',ev=>{soundOn=!soundOn;ev.currentTarget.classList.toggle('active',soundOn);ev.currentTarget.title=soundOn?'Sound on':'Sound off'});
function putCircle(cx,cy,r,type){for(let y=-r;y<=r;y++)for(let x=-r;x<=r;x++)if(x*x+y*y<=r*r)setCell(cx+x,cy+y,type)}
function loadScene(kind){cells.fill(0);age.fill(0);const floor=H-5;for(let x=0;x<W;x++)for(let y=floor;y<H;y++)setCell(x,y,STONE);
 if(kind==='hourglass'){setScene('Hourglass');for(let y=12;y<63;y++)for(let x=48;x<152;x++)if(Math.abs(x-100)<(y<37?48-(y-12)*.95:24+(y-37)*.95))setCell(x,y,WOOD);for(let y=18;y<53;y++)for(let x=71;x<129;x++)if(Math.abs(x-100)<(y<35?(y-18)*1.3: (53-y)*1.3))setCell(x,y,SAND);for(let x=48;x<152;x++)setCell(x,63,WOOD);}
 if(kind==='garden'){setScene('Tiny garden');for(let x=0;x<W;x++)for(let y=floor-3;y<floor;y++)setCell(x,y,SAND);for(let n=0;n<80;n++)setCell(18+Math.random()*164|0,floor-4,SEED);for(let x=24;x<86;x++)for(let y=82;y<floor-3;y++)if(Math.random()<.54)setCell(x,y,WATER);}
 if(kind==='campfire'){setScene('Campfire');for(let x=79;x<122;x++){setCell(x,floor-1,WOOD)}for(let n=0;n<30;n++)putCircle(100,floor-4,n%3+1,FIRE);for(let x=68;x<83;x++)setCell(x,floor-2,WOOD);for(let x=118;x<133;x++)setCell(x,floor-2,WOOD);}
 if(kind==='waterfall'){setScene('Waterfall');for(let x=22;x<178;x++)if(x<44||x>155)for(let y=48;y<H;y++)setCell(x,y,STONE);for(let x=44;x<156;x++)for(let y=floor-2;y<floor;y++)setCell(x,y,STONE);for(let x=78;x<122;x++)for(let y=8;y<55;y++)setCell(x,y,WATER);for(let x=60;x<140;x++)for(let y=66;y<floor-2;y++)if(Math.random()<.72)setCell(x,y,WATER);}
 countParticles();render()}
document.querySelectorAll('.preset').forEach(b=>b.addEventListener('click',()=>loadScene(b.dataset.scene)));
window.addEventListener('keydown',ev=>{if(ev.code==='Space'){ev.preventDefault();togglePause()}if(ev.key>='1'&&ev.key<='6')selectMaterial(mats[Number(ev.key)-1].id);if(ev.key==='Escape'){clearWorld();render()}});
function loop(){if(running)update();render();requestAnimationFrame(loop)}
loadScene('hourglass');requestAnimationFrame(loop);
</script>
</body>
</html>

